import{_ as r,C as s,c as n,o as i,a3 as e,G as a}from"./chunks/framework.Dokpd4od.js";const k=JSON.parse('{"title":"Work locations","description":"","frontmatter":{},"headers":[],"relativePath":"master/human-resources/employees/setup/work-locations.md","filePath":"master/human-resources/employees/setup/work-locations.md","lastUpdated":1791902625000}'),l={name:"master/human-resources/employees/setup/work-locations.md"};function c(d,o,p,m,h,u){const t=s("ImagePopup");return i(),n("div",null,[o[0]||(o[0]=e('<h1 id="work-locations" tabindex="-1">Work locations <a class="header-anchor" href="#work-locations" aria-label="Permalink to &quot;Work locations&quot;">​</a></h1><p>A work location tells everyone where a person usually works: at an office, at home, or somewhere else. You set it once per place and pick it on each employee. This helps you see who is on site and who works remotely.</p><blockquote><p><strong>In simple words:</strong> A work location is the place an employee works from.</p></blockquote><p>Open <code>Employees → Configurations → Work Locations</code>.</p><div class="info custom-block"><p class="custom-block-title">Prerequisite</p><p>None. The sample data has <strong>Home</strong>, <strong>Building 1, Second Floor</strong> and <strong>Other</strong>.</p></div><h2 id="overview" tabindex="-1">Overview <a class="header-anchor" href="#overview" aria-label="Permalink to &quot;Overview&quot;">​</a></h2><p>Four tabs filter the list by kind: <strong>All</strong>, <strong>Office</strong>, <strong>Home</strong> and <strong>Other</strong>. Columns are <strong>Name</strong>, <strong>Location Type</strong>, <strong>Status</strong> and <strong>Company</strong>. You can filter by <strong>Status</strong>.</p>',7)),a(t,{src:"/images1/employees/set_worklocation_list.png",alt:"Work Locations list with tabs All, Office, Home and Other and the columns Name, Location Type, Status and Company"}),o[1]||(o[1]=e('<h2 id="create-a-work-location" tabindex="-1">Create a work location <a class="header-anchor" href="#create-a-work-location" aria-label="Permalink to &quot;Create a work location&quot;">​</a></h2><p>This example adds a second office.</p><ol><li>Open <code>Employees → Configurations → Work Locations</code>.</li><li>Click <strong>New Work Location</strong>. A window opens.</li><li>Fill in the form.</li></ol><ul><li><strong><em>Name:</em></strong> Required. Type <code>Warehouse Block A</code>.</li><li><strong><em>Location Type:</em></strong> Required. Click <strong>Office</strong>. The other choices are <strong>Home</strong> and <strong>Other</strong>. Nothing is chosen at first.</li><li><strong><em>Location Number:</em></strong> Optional. A room or building number, such as <code>B-12</code>.</li><li><strong><em>Company:</em></strong> Required. Fills with <strong>My Company</strong>.</li><li><strong><em>Status:</em></strong> Required toggle. Default is off. Turn it on.</li></ul>',4)),a(t,{src:"/images1/employees/set_worklocation_form.png",alt:"Create Work Locations window with Warehouse Block A, Location Type Office, number B-12, My Company and Status on"}),o[2]||(o[2]=e('<ol start="4"><li>Click <strong>Create</strong>.</li></ol><div class="warning custom-block"><p class="custom-block-title">WARNING</p><p><strong>Status</strong> is off by default. Turn it on, or the location stays inactive.</p></div><h2 id="where-work-locations-are-used" tabindex="-1">Where work locations are used <a class="header-anchor" href="#where-work-locations-are-used" aria-label="Permalink to &quot;Where work locations are used&quot;">​</a></h2><ul><li>On the employee form, <code>Work Information → Location → Work Location</code> offers these records. The plus button next to it creates one on the spot.</li><li>Changing the employee&#39;s company clears the work location, so you pick again.</li><li>The tab on this list groups places by type, which helps you review office and home setups.</li></ul><h2 id="edit-or-delete" tabindex="-1">Edit or delete <a class="header-anchor" href="#edit-or-delete" aria-label="Permalink to &quot;Edit or delete&quot;">​</a></h2><p>Click <strong>Edit</strong> on a row to change it. Click <strong>Delete</strong> to remove it.</p><h2 id="see-also" tabindex="-1">See also <a class="header-anchor" href="#see-also" aria-label="Permalink to &quot;See also&quot;">​</a></h2><ul><li><a href="./../employees/add-employee.html">Add an employee</a></li><li><a href="./../get-started/first-steps.html">First steps</a></li><li><a href="./">Setup overview</a></li></ul>',8))])}const f=r(l,[["render",c]]);export{k as __pageData,f as default};
